let exactCandidates = 0, roundtripCandidates = 0;
for (const reference of REFERENCES) {
  const candidates = candidateEncodings(reference.text), selected = selectCandidate(reference.text);
  assert.deepEqual(candidates.map(costs), reference.candidates, reference.name);
  assert.deepEqual(costs(selected), reference.selected, reference.name);
  assert.equal(toHex(selected.blob).replaceAll(' ', ''), reference.hex, reference.name);
  for (let i = 0; i < candidates.length; i++) {
    const candidate = candidates[i];
    assert.equal(candidate.blob.length, candidate.header_bytes + candidate.model_bytes + candidate.residual_bytes);
    assert.equal(decode(candidate.blob), reference.text, `${reference.name}/${candidate.name}`);
    if (reference.all_hex) assert.equal(toHex(candidate.blob).replaceAll(' ', ''), reference.all_hex[i]);
    exactCandidates++;
  }
  assert.deepEqual(encode(reference.text), selected.blob);
  assert.equal(analyze(reference.text).restored, reference.text);
  assert.deepEqual(fromHex(toHex(selected.blob)), selected.blob);
  // No proper prefix of an encoded frame is valid.
  for (let end = 0; end < selected.blob.length; end++) assert.throws(() => decode(selected.blob.slice(0,end)), CodecError);
  assert.throws(() => decode(Uint8Array.from([...selected.blob,0])), CodecError);
}
