for (let trial = 0; trial < 450; trial++) {
  const length = next() % 150;
  const text = Array.from({length}, () => alphabet[next() % alphabet.length]).join('');
  const candidates = candidateEncodings(text), selected = chooseCandidate(candidates);
  assert.equal(candidates.length, 1 + Math.min(16, length));
  assert.equal(selected.total_bytes, Math.min(...candidates.map(candidate => candidate.total_bytes)));
  assert.ok(selected.total_bytes <= candidates[0].total_bytes);
  for (const candidate of candidates) {
    assert.equal(decode(candidate.blob), text);
    assert.equal(candidate.blob.length, candidate.header_bytes + candidate.model_bytes + candidate.residual_bytes);
    roundtripCandidates++;
  }
}
