class Element {
  constructor(tag = 'div') { this.tagName=tag; this.children=[]; this.handlers={}; this.attributes={}; this.dataset={}; this.style={}; this.value=''; this.textContent=''; this.hidden=false; this.className=''; }
  append(...children) { this.children.push(...children); }
  replaceChildren(...children) { this.children=[...children]; }
  setAttribute(key,value) { this.attributes[key]=String(value); }
  addEventListener(event,fn) { (this.handlers[event] ||= []).push(fn); }
  querySelectorAll(selector) { return this.children.flatMap(child => [ ...(child.tagName === selector ? [child] : []), ...child.querySelectorAll(selector)]); }
  dispatch(event) { for (const fn of this.handlers[event] || []) fn(); }
}
